-- PT106-S1-Q6. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT106-S1-Q6$batch06$ AND q.stimulus=$batch06$Hospital auditor: The Rodriguez family stipulated that the funds they donated to the neurological clinic all be used to minimize patients' suffering. The clinic administration is clearly violating those terms, since it has allocated nearly one fifth of those funds for research into new diagnostic technologies, instead of letting that money flow directly to its patients.

Clinic administrator: But the successful development of new technologies will allow early diagnosis of many neurological disorders. In most cases, patients who are treated in the early stages of neurological disorders suffer far less than do patients who are not treated until their neurological disorders reach advanced stages.$batch06$ AND q.prompt=$batch06$Which one of the following is the main point at issue between the hospital auditor and the clinic administrator?$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT106-S1-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT106-S1-Q6$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S1-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT106-S1-Q6$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Hospital auditor's Position$batch06$, $batch06$The clinic is violating the family's terms by spending a fifth of the money on research instead of patients.$batch06$), (1, $batch06$Clinic administrator's Position$batch06$, $batch06$The research leads to early diagnosis, and early treatment means far less suffering.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The administrator never says "we are following the terms." But the reply only makes sense as a defense: research *does* minimize suffering, so spending on it fits the family's condition. Underneath, they disagree about whether the clinic is following the terms.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether the clinic is following the family's conditions.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT106-S1-Q6$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Only the administrator talks about the effect of early treatment, and "rather than completely eliminating" adds a distinction neither makes.$batch06$), ($batch06$B$batch06$, $batch06$Neither speaker discusses whether current patients get adequate treatment.$batch06$), ($batch06$C$batch06$, $batch06$Both accept the family's stipulation. They disagree about whether the clinic is honoring it.$batch06$), ($batch06$D$batch06$, $batch06$The auditor says the clinic is violating the terms. The administrator's reply is a defense that it is not.$batch06$), ($batch06$E$batch06$, $batch06$What the family anticipated never comes up.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT106-S1-Q6$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
